def minhash(shingles, n=128):
    sig = [UINT32_MAX] * n
    for sh in shingles:                  # sh is a 64-bit shingle hash
        for i in range(n):
            h = (A[i] * sh + B[i]) % P % 2**32
            if h < sig[i]: sig[i] = h
    return sig

def bands(sig, b=32, r=4):
    return [(i, hash64(tuple(sig[i*r:(i+1)*r]))) for i in range(b)]

def candidates(sig):
    ids = set()
