        if bucket.size >= 10_000: continue        # boilerplate bucket
        ids |= bucket.ids
    return ids

def est_jaccard(a, b):
    return sum(x == y for x, y in zip(a, b)) / len(a)

def simhash(tokens_with_weights):
    v = [0] * 64
    for tok, w in tokens_with_weights:       # w = tf-idf weight
        h = hash64(tok)
        for i in range(64):
            v[i] += w if (h >> i) & 1 else -w
    return sum(1 << i for i in range(64) if v[i] > 0)

def near(fp, k=3):
    out = set()
    for t in range(4):
        block = (fp >> (16 * t)) & 0xFFFF
        for cand_id, cand_fp in simhash_table[t].get(block):
            if popcount(fp ^ cand_fp) <= k: out.add(cand_id)
    return out
